// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract Splitter {
    // Divide `total` proporzionalmente ai pesi. Ogni quota è arrotondata per difetto:
    // la somma delle quote può essere minore di total; la differenza è il "resto" (dust).
    function split(uint256 total, uint256[] calldata weights)
        external pure returns (uint256[] memory shares, uint256 dust)
    {
        uint256 sumW = 0;
        for (uint256 i = 0; i < weights.length; i++) sumW += weights[i];
        require(sumW > 0, "pesi nulli");
        shares = new uint256[](weights.length);
        uint256 given = 0;
        for (uint256 i = 0; i < weights.length; i++) {
            shares[i] = total * weights[i] / sumW;   // prima moltiplico, poi divido
            given += shares[i];
        }
        dust = total - given;
    }

    // Versione sbagliata: divide prima e moltiplica dopo
    function shareWrong(uint256 total, uint256 w, uint256 sumW) external pure returns (uint256) {
        return total / sumW * w;
    }
}

