contract Inbox {
    event ViaReceive(address indexed from, uint256 value);
    event ViaFallback(address indexed from, uint256 value, bytes4 sig);
    event ViaDeposit(address indexed from, uint256 value);

    mapping(address => uint256) public credit;

    receive() external payable {                 // calldata vuota
        credit[msg.sender] += msg.value;
        emit ViaReceive(msg.sender, msg.value);
    }

    fallback() external payable {                // selettore sconosciuto
        credit[msg.sender] += msg.value;
        emit ViaFallback(msg.sender, msg.value, msg.sig);
    }

    function deposit() external payable {
        credit[msg.sender] += msg.value;
        emit ViaDeposit(msg.sender, msg.value);
    }

    function ping() external pure returns (string memory) { return "pong"; }
}

