// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract Owned {
    address public owner;
    error NotOwner(address caller);

    constructor() { owner = msg.sender; }

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner(msg.sender);
        _;
    }
}

contract Offer is Owned {
    uint256 public immutable deadline;   // numero di blocco
    bool public active = true;
    uint256 public accepted;

    event Accepted(address indexed by, uint256 total);
    event Deactivated(uint256 atBlock);

    constructor(uint256 durationBlocks) { deadline = block.number + durationBlocks; }

    modifier whenActive() {
        require(active, "contratto disattivato");
        _;
    }

    modifier before(uint256 blockNumber) {
        require(block.number < blockNumber, "scaduto");
        _;
    }

    // i modificatori sono valutati nell'ordine in cui compaiono
    function accept() external whenActive before(deadline) {
        accepted += 1;
        emit Accepted(msg.sender, accepted);
    }

    // al posto di selfdestruct: si cambia lo stato e tutte le funzioni revertono
    function deactivate() external onlyOwner whenActive {
        active = false;
        emit Deactivated(block.number);
    }
}

