// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract PullPayments {
    mapping(address => uint256) public owed;
    event Credited(address indexed to, uint256 value);
    event Withdrawn(address indexed to, uint256 value);

    // chi paga accredita, non invia (push): nessuna chiamata esterna qui
    function payTo(address to) external payable {
        require(msg.value > 0, "niente valore");
        owed[to] += msg.value;
        emit Credited(to, msg.value);
    }

    // il destinatario ritira (pull): checks - effects - interactions
    function withdraw() external {
        uint256 v = owed[msg.sender];                 // check
        require(v > 0, "nulla da ritirare");
        owed[msg.sender] = 0;                         // effect
        (bool ok, ) = payable(msg.sender).call{value: v}("");   // interaction
        require(ok, "invio fallito");
        emit Withdrawn(msg.sender, v);
    }

    // confronto: push con transfer (2300 gas)
    function pushWithTransfer(address payable to) external payable {
        to.transfer(msg.value);
    }
}

// destinatario "normale": la receive scrive in storage (>2300 gas)
contract Wallet {
    uint256 public received;
    receive() external payable { received += msg.value; }
    function pull(PullPayments p) external { p.withdraw(); }
}

